"""Serve transaction scores from the model bundle generated by src.train."""

import os
from contextlib import asynccontextmanager
from pathlib import Path
from typing import Annotated

import joblib
import pandas as pd
from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field, FiniteFloat

FEATURE_COLUMNS = [f"V{i}" for i in range(1, 29)] + ["Amount"]
DEFAULT_MODEL = Path(__file__).resolve().parents[1] / "models/xgb_model.joblib"


@asynccontextmanager
async def lifespan(app: FastAPI):
    path = Path(os.environ.get("FRAUD_MODEL_PATH", DEFAULT_MODEL))
    if not path.is_file():
        raise RuntimeError(f"Model artifact {path} is missing. Run python -m src.train first.")

    bundle = joblib.load(path)
    if bundle.get("feature_columns", FEATURE_COLUMNS) != FEATURE_COLUMNS:
        raise ValueError("The trained model must expect V1 through V28 followed by Amount.")
    threshold = float(bundle["threshold"])
    if not (0 <= threshold <= 1 or threshold == float("inf")):
        raise ValueError("The model threshold must be between zero and one or positive infinity.")
    app.state.bundle = bundle
    app.state.threshold = None if threshold == float("inf") else threshold
    yield


app = FastAPI(title="Fraud Detection API", version="1.0.0", lifespan=lifespan)


class Transaction(BaseModel):
    v: list[Annotated[FiniteFloat, Field(strict=True)]] = Field(
        min_length=28, max_length=28, description="V1 to V28 in order"
    )
    amount: Annotated[FiniteFloat, Field(strict=True, ge=0, description="Original transaction amount")]


class Health(BaseModel):
    status: str
    threshold: float | None


class Prediction(BaseModel):
    fraud_score: float
    is_fraud_alert: bool
    threshold: float | None


@app.exception_handler(RequestValidationError)
async def invalid_transaction(request: Request, exc: RequestValidationError) -> JSONResponse:
    # Raw inputs may contain non-finite numbers that cannot be echoed in JSON.
    errors = [{key: error[key] for key in ("loc", "msg", "type")} for error in exc.errors()]
    return JSONResponse(status_code=422, content={"detail": errors})


@app.get("/health")
def health(request: Request) -> Health:
    return Health(status="ok", threshold=request.app.state.threshold)


@app.post("/predict")
def predict(transaction: Transaction, request: Request) -> Prediction:
    bundle = request.app.state.bundle
    threshold = request.app.state.threshold
    row = pd.DataFrame([[*transaction.v, transaction.amount]], columns=FEATURE_COLUMNS)
    features = bundle["preprocessor"].transform(row)
    score = float(bundle["model"].predict_proba(features)[0, 1])
    return Prediction(
        fraud_score=score,
        is_fraud_alert=threshold is not None and score >= threshold,
        threshold=threshold,
    )
